# 企业客户数据分析程序 (C++ 版本)

```cpp
#include <iostream>
#include <fstream>
#include <filesystem>
#include <thread>
#include <mutex>
#include <map>
#include <vector>
#include <ctime>
#include <regex>
#include <chrono>
#include <cmath>
#include <sstream>
#include <iomanip>
#include <algorithm>
#include <thread>
#include <future>
#include <algorithm>
#include <iomanip>
#include <cctype>

namespace fs = std::filesystem;

// 配置参数
struct Config {
    std::string data_dir = "data/";
    std::string db_config = "localhost:5432:enterprise_db:admin:admin123";
    int max_threads = 4;
};

// 日志记录
std::mutex log_mutex;
void log(const std::string& message) {
    std::lock_guard<std::mutex> lock(log_mutex);
    std::ofstream log_file("data_analysis.log", std::ios::app);
    auto now = std::chrono::system_clock::now();
    std::time_t now_time = std::chrono::system_clock::to_time_t(now);
    log_file << std::ctime(&now_time) << " - " << message << std::endl;
}

// 数据清洗工具
class DataCleaner {
public:
    std::string clean_text(const std::string& text) {
        std::string result;
        std::regex pattern("[^a-zA-Z0-9\\s]");
        result = std::regex_replace(text, pattern, " ");
        std::regex space_pattern("\\s+");
        result = std::regex_replace(result, space_pattern, " ");
        std::transform(result.begin(), result.end(), result.begin(), ::tolower);
        return result;
    }

    std::tm clean_time(const std::string& timestamp) {
        std::tm time_info = {};
        std::istringstream ss(timestamp);
        ss >> std::get_time(&time_info, "%Y-%m-%d %H:%M:%S");
        if (ss.fail()) {
            ss.clear();
            ss.str(timestamp);
            ss >> std::get_time(&time_info, "%Y-%m-%d");
        }
        return time_info;
    }
};

// 自然语言处理工具
class NLPAnalyzer {
public:
    std::string sentiment_analysis(const std::string& text) {
        // 这里简化为关键词判断
        if (text.find("good") != std::string::npos || text.find("great") != std::string::npos) {
            return "positive";
        }
        if (text.find("bad") != std::string::npos || text.find("poor") != std::string::npos) {
            return "negative";
        }
        return "neutral";
    }
};

// 数据处理类
class DataProcessor {
private:
    DataCleaner cleaner;
    NLPAnalyzer nlp;
    std::map<std::string, std::map<std::string, int>> chat_stats;
    std::map<std::tm, double> daily_sales;
    std::mutex stats_mutex;

public:
    void process_file(const std::string& file_path) {
        log("开始处理文件: " + file_path);

        std::ifstream file(file_path);
        if (!file) {
            log("文件打开失败: " + file_path);
            return;
        }

        std::string line;
        if (file_path.find(".json") != std::string::npos) {
            // JSON文件处理
            while (std::getline(file, line)) {
                if (line.find("chat") != std::string::npos) {
                    _process_chat_data(line);
                } else if (line.find("transaction") != std::string::npos) {
                    _process_transaction_data(line);
                }
            }
        } else if (file_path.find(".csv") != std::string::npos) {
            // CSV文件处理
            std::string header;
            std::getline(file, header);
            while (std::getline(file, line)) {
                if (line.find("chat") != std::string::npos) {
                    _process_chat_data(line);
                } else if (line.find("transaction") != std::string::npos) {
                    _process_transaction_data(line);
                }
            }
        }

        log("成功处理文件: " + file_path);
    }

    void _process_chat_data(const std::string& data) {
        // 解析聊天数据
        std::string request_time, response_time, query, response;
        // 简化解析逻辑
        size_t pos = data.find("request_time");
        if (pos != std::string::npos) {
            request_time = data.substr(pos + 13, 20);
        }

        pos = data.find("response_time");
        if (pos != std::string::npos) {
            response_time = data.substr(pos + 14, 20);
        }

        pos = data.find("query");
        if (pos != std::string::npos) {
            query = data.substr(pos + 7, 100);
        }

        pos = data.find("response");
        if (pos != std::string::npos) {
            response = data.substr(pos + 9, 100);
        }

        if (!request_time.empty() && !response_time.empty() && !query.empty() && !response.empty()) {
            auto request_time_clean = cleaner.clean_time(request_time);
            auto response_time_clean = cleaner.clean_time(response_time);
            double response_time_seconds = std::difftime(mktime(&response_time_clean), mktime(&request_time_clean));

            std::string cleaned_query = cleaner.clean_text(query);
            std::string cleaned_response = cleaner.clean_text(response);

            if (!cleaned_query.empty() && !cleaned_response.empty()) {
                std::lock_guard<std::mutex> lock(stats_mutex);
                std::string agent_id = "agent_001"; // 示例客服ID
                chat_stats[agent_id]["total_chats"]++;
                chat_stats[agent_id]["avg_response_time"] += response_time_seconds;
                chat_stats[agent_id][nlp.sentiment_analysis(cleaned_response)]++;
            }
        }
    }

    void _process_transaction_data(const std::string& data) {
        // 解析交易数据
        std::string timestamp, product, amount;
        // 简化解析逻辑
        size_t pos = data.find("timestamp");
        if (pos != std::string::npos) {
            timestamp = data.substr(pos + 10, 20);
        }

        pos = data.find("product");
        if (pos != std::string::npos) {
            product = data.substr(pos + 8, 50);
        }

        pos = data.find("amount");
        if (pos != std::string::npos) {
            amount = data.substr(pos + 7, 10);
        }

        if (!timestamp.empty() && !product.empty() && !amount.empty()) {
            auto time_clean = cleaner.clean_time(timestamp);
            std::string cleaned_product = cleaner.clean_text(product);
            double amount_value = std::stod(amount);

            std::lock_guard<std::mutex> lock(stats_mutex);
            daily_sales[mktime(&time_clean)] += amount_value;
        }
    }

    void generate_report() {
        // 计算平均响应时间
        for (auto& [agent, stats] : chat_stats) {
            if (stats["total_chats"] > 0) {
                stats["avg_response_time"] /= stats["total_chats"];
            }
        }

        // 生成文本报告
        std::ofstream report("daily_report.txt");
        report << "Daily Business Report\n";
        report << "-----------------------\n";
        report << "Total Chat Files: " << chat_stats.size() << "\n";
        report << "Total Sales: $" << std::accumulate(daily_sales.begin(), daily_sales.end(), 0.0, 
            [](double sum, const auto& p) { return sum + p.second; }) << "\n";
    }
};

// 主程序
class DataAnalysisApp {
private:
    Config config;
    DataProcessor processor;
    std::chrono::time_point<std::chrono::steady_clock> start_time;

public:
    void run() {
        start_time = std::chrono::steady_clock::now();
        log("程序开始运行");

        try {
            // 多线程处理文件
            std::vector<std::future<void>> futures;
            for (const auto& entry : fs::recursive_directory_iterator(config.data_dir)) {
                if (entry.path().extension() == ".json" || entry.path().extension() == ".csv") {
                    futures.push_back(std::async(std::launch::async, &DataProcessor::process_file, &processor, entry.path()));
                }
            }

            // 等待所有任务完成
            while (futures.size() > 0) {
                _print_progress();
                std::this_thread::sleep_for(std::chrono::seconds(1));
                futures.erase(std::remove_if(futures.begin(), futures.end(), 
                    [](auto& f) { return f.wait_for(std::chrono::seconds(0)) == std::future_status::ready; }), futures.end());
            }

            // 生成报告
            processor.generate_report();
            log("程序执行完成");

        } catch (const std::exception& e) {
            log("程序执行异常: " + std::string(e.what()));
        }
    }

    void _print_progress() {
        auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - start_time).count();
        double processed_files = processor.chat_stats.size() + processor.daily_sales.size();
        double progress = (processed_files / 100.0) * 100; // 示例进度计算
        double rate = processed_files / (elapsed > 0 ? elapsed : 1);
        std::cout << "\rProgress: " << std::fixed << std::setprecision(2) << progress << "% | Rate: " << rate << " files/sec" << std::flush;
    }
};

int main() {
    DataAnalysisApp app;
    app.run();
    return 0;
}
```

## 转换说明

1. **核心功能保留**：
   - 数据清洗功能保持不变
   - 多线程处理文件
   - 聊天记录和交易数据处理
   - 基本的统计分析

2. **C++ 特性**：
   - 使用标准库实现基本功能
   - 使用多线程处理文件
   - 使用 mutex 保证线程安全
   - 使用文件系统库处理文件

3. **简化实现**：
   - 使用更简单的数据解析方式
   - 使用文本文件代替PDF报告
   - 简化了时间处理逻辑

4. **关键组件**：
   - `DataCleaner`类实现了文本和时间清洗
   - `NLPAnalyzer`类实现了基本的情感分析
   - `DataProcessor`类处理文件并生成统计
