### 📌 完全なC++コード（コメント付き）

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <filesystem>
#include <regex>
#include <ctime>
#include <map>
#include <nlohmann/json.hpp>
#include "sqlite3.h"
#include "cppjieba/Jieba.hpp"

// ファイルシステムとJSONライブラリの名前空間を短縮
namespace fs = std::filesystem;
using json = nlohmann::json;

// 初期設定
const std::string DATA_DIR = "./data";       // データを読み込むディレクトリ
const std::string DB_PATH = "analytics.db";  // 出力先のデータベースファイル
// cppjieba辞書のパス（必要に応じて変更）
cppjieba::Jieba jieba("dict/jieba.dict.utf8", "dict/hmm_model.utf8", "dict/idf.utf8", "dict/stop_words.utf8");

// ログ出力関数
// ログにはタイムスタンプを含めて、処理の流れを追跡可能に
void log_message(const std::string& msg) {
    std::time_t now = std::time(nullptr);
    char buffer[100];
    std::strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", std::localtime(&now));
    std::cout << "[" << buffer << "] " << msg << std::endl;
}

// データ読み込み関数
// JSONファイルを読み込み、JSONオブジェクトのベクターとして返す
std::vector<json> load_data() {
    std::vector<json> records;
    log_message("Starting data loading from directory: " + DATA_DIR);

    // ディレクトリ内のファイルを走査
    for (const auto& file : fs::directory_iterator(DATA_DIR)) {
        // 拡張子が ".json" であるファイルのみ処理
        if (file.path().extension() == ".json") {
            std::ifstream f(file.path());
            if (!f.is_open()) {
                log_message("Failed to open file: " + file.path().string());
                continue;
            }
            f >> records;  // JSONを読み込み
            log_message("Loaded JSON file: " + file.path().string());
        }
    }

    return records;
}

// データクリーニング関数
// 不要なレコードを除外し、フォーマットを統一
std::vector<json> clean_data(const std::vector<json>& raw) {
    std::vector<json> cleaned;
    std::map<std::string, bool> seen;  // 重複を検出するためのマップ

    log_message("Starting data cleaning process");

    for (const auto& rec : raw) {
        // 必須フィールドが存在しない場合はスキップ
        if (!rec.contains("timestamp") || !rec.contains("customer_id") || !rec.contains("message")) {
            continue;
        }

        // 重複を検出するユニークキーを生成
        std::string key = rec["timestamp"].get<std::string>() + "-" + rec["customer_id"].get<std::string>();
        if (seen.count(key)) {
            continue;  // 既に存在するキーならスキップ
        }
        seen[key] = true;

        // 時間フォーマットを統一（例: "2025-04-05 12:34:56"）
        std::tm tm = {};
        std::istringstream ss(rec["timestamp"]);
        ss >> std::get_time(&tm, "%Y-%m-%d %H:%M:%S");
        if (ss.fail()) {
            continue;  // フォーマットが不正な場合
        }
        std::time_t t = std::mktime(&tm);
        rec["timestamp"] = std::ctime(&t);  // 標準フォーマットに変換

        // テキストのクリーン（特殊文字除去と空白の統一）
        std::string text = rec["message"].get<std::string>();
        text = std::regex_replace(text, std::regex(R"([^\w\s])"), "");  // 特殊文字を除去
        text = std::regex_replace(text, std::regex(R"(\s+)"), " ");     // 空白を1つに統一
        rec["message"] = text;

        cleaned.push_back(rec);
    }

    log_message("Data cleaning completed. Cleaned " + std::to_string(cleaned.size()) + " records.");
    return cleaned;
}

// 感情分析関数（簡易版）
// テキストから「好」や「差」などの単語を抽出し、スコアを返す
double analyze_sentiment(const std::string& text) {
    auto words = jieba.cut(text);  // 中国語を単語に分割
    double score = 0.0;

    for (const auto& word : words) {
        if (word == "好") score += 0.2;  // 「好」があればポジティブスコア
        if (word == "差") score -= 0.2;  // 「差」があればネガティブスコア
    }

    return score;
}

// DB初期化関数
// SQLiteデータベースを開き、テーブルを作成
void init_db(sqlite3*& db) {
    log_message("Initializing database: " + DB_PATH);

    int rc = sqlite3_open(DB_PATH.c_str(), &db);
    if (rc != SQLITE_OK) {
        log_message("Failed to open database.");
        return;
    }

    // テーブルが存在しない場合は作成
    sqlite3_exec(db, "CREATE TABLE IF NOT EXISTS chat_analytics (id INTEGER PRIMARY KEY, message TEXT, sentiment REAL);", 0, 0, 0);
    sqlite3_exec(db, "CREATE TABLE IF NOT EXISTS sales_analytics (date TEXT, count INTEGER);", 0, 0, 0);

    log_message("Database initialized.");
}

// DB書き込み関数
// 感情分析結果や集計結果をデータベースに保存
void write_to_db(sqlite3* db, const json& data, const std::string& table) {
    std::string sql;

    if (table == "chat_analytics") {
        sql = "INSERT INTO chat_analytics (message, sentiment) VALUES ('" + data["message"] + "', " + std::to_string(data["sentiment"]) + ");";
    } else if (table == "sales_analytics") {
        sql = "INSERT INTO sales_analytics (date, count) VALUES ('" + data["date"] + "', " + std::to_string(data["count"]) + ");";
    }

    // SQL実行
    char* errMsg = nullptr;
    if (sqlite3_exec(db, sql.c_str(), 0, 0, &errMsg) != SQLITE_OK) {
        log_message("DB Error: " + std::string(errMsg));
        sqlite3_free(errMsg);
    }
}

// メイン処理
int main() {
    log_message("Customer Analytics Service Starting");

    sqlite3* db;
    init_db(db);  // DB初期化

    auto raw_data = load_data();        // データを読み込む
    auto cleaned_data = clean_data(raw_data);  // データをクリーン

    // 感情分析とDB保存
    for (auto& rec : cleaned_data) {
        double sentiment = analyze_sentiment(rec["message"]);
        rec["sentiment"] = sentiment;
        write_to_db(db, rec, "chat_analytics");
    }

    // 日次集計（簡易版）
    std::map<std::string, int> daily_sales;
    for (auto& rec : cleaned_data) {
        if (rec["type"] == "transaction") {
            std::string date = rec["timestamp"].substr(0, 10);  // 日付部分のみ取得
            daily_sales[date]++;  // その日付のカウントを増やす
        }
    }

    // 日次集計結果をDBに保存
    for (const auto& [date, count] : daily_sales) {
        json j = { {"date", date}, {"count", count} };
        write_to_db(db, j, "sales_analytics");
    }

    log_message("Batch processing completed.");
    sqlite3_close(db);  // DBを閉じる
    return 0;
}
```

