#include <ctime>
#include <filesystem>
#include <regex>
#include <thread>
#include <chrono>

namespace fs = std::filesystem;

// Function: analyze_sentiment
// Purpose: A simplified sentiment analyzer using a dictionary of known sentiment words.
// Input: A string of text (e.g., a customer service chat message)
// Output: A sentiment score (positive, neutral, or negative)
// Note: This is a basic version. For real applications, consider using an NLP library.
double analyze_sentiment(const std::string& text) {
    std::unordered_map<std::string, int> sentiment_words = {
        {"good", 1}, {"great", 2}, {"excellent", 3},
        {"bad", -1}, {"terrible", -2}, {"awful", -3}
    };
    double score = 0;
    std::istringstream iss(text);
    std::string word;
    while (iss >> word) {
        std::transform(word.begin(), word.end(), word.begin(), ::tolower);
        if (sentiment_words.count(word)) score += sentiment_words[word];
    }
    return score;
}

// Function: preprocess_text
// Purpose: Clean text by removing special characters and converting to lowercase
// Input: Raw text string
// Output: Cleaned and normalized text string
std::string preprocess_text(const std::string& text) {
    std::string result;
    for (char c : text) {
        if (std::isalnum(c) || std::isspace(c)) {
            result += std::tolower(c);
        }
    }
    return result;
}

// Function: deduplicate
// Purpose: Remove duplicate records based on an ID field (assumed to be the first field in CSV)
// Input: A vector of CSV lines
// Output: A vector of unique lines
std::vector<std::string> deduplicate(const std::vector<std::string>& lines) {
    std::unordered_set<std::string> seen;
    std::vector<std::string> result;
    for (const auto& line : lines) {
        std::istringstream iss(line);
        std::string id;
        std::getline(iss, id, ','); // Assume first field is ID
        if (!id.empty() && seen.insert(id).second) {
            result.push_back(line);
        }
    }
    return result;
}

// Function: read_file
// Purpose: Read a CSV file line by line into a vector of strings
// Input: Path to the file
// Output: Vector of lines (each line is a CSV record)
std::vector<std::string> read_file(const std::string& path) {
    std::ifstream file(path);
    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) lines.push_back(line);
    return lines;
}

// Function: process_chat
// Purpose: Analyze a single chat message for sentiment and output the result
// Input: Raw chat message text
// Output: Prints sentiment score and cleaned text to console
void process_chat(const std::string& text) {
    std::string clean_text = preprocess_text(text);
    double sentiment = analyze_sentiment(clean_text);
    std::cout << "Sentiment: " << sentiment << "\nCleaned Text: " << clean_text << "\n\n";
}

// Function: process_file
// Purpose: Process a CSV file by reading, deduplicating, and analyzing each record
// Input: Path to the CSV file
void process_file(const std::string& path) {
    std::cout << "Processing file: " << path << "\n";
    auto lines = read_file(path);
    auto cleaned = deduplicate(lines);
    for (const auto& line : cleaned) {
        std::istringstream iss(line);
        std::string id, date, message;
        std::getline(iss, id, ',');
        std::getline(iss, date, ',');
        std::getline(iss, message, ',');
        process_chat(message);
    }
}

// Function: monitor_directory
// Purpose: Continuously monitor a directory for new CSV files and process them
// Input: Path to the directory to monitor
void monitor_directory(const std::string& dir_path) {
    while (true) {
        for (const auto& entry : fs::directory_iterator(dir_path)) {
            if (entry.is_regular_file() && entry.path().extension() == ".csv") {
                process_file(entry.path().string());
            }
        }
        std::this_thread::sleep_for(std::chrono::seconds(10));
    }
}

// Main function
// Entry point of the program
int main() {
    std::string data_dir = "customer_data"; // Replace with your actual data directory
    std::cout << "Starting C++ data processing system...\n";
    monitor_directory(data_dir); // Start monitoring for new files
    return 0;
}
```

---

### 📌 Function-by-Function Summary

| Function | Purpose |
|----------|---------|
| `analyze_sentiment` | Analyzes text for sentiment using a basic dictionary. |
| `preprocess_text` | Cleans text by removing special characters and lowercasing. |
| `deduplicate` | Prevents processing duplicate records by checking the first field (ID). |
| `read_file` | Reads a CSV file into a list of strings. |
| `process_chat` | Analyzes a single chat message and prints results. |
| `process_file` | Processes an entire CSV file (deduplicate, analyze, and output). |
| `monitor_directory` | Continuously scans a directory for new files and processes them. |
| `main` | Entry point and starts the monitoring process. |

